const defaultCode = '# Your first spell\nname = "Alex"\nprint("Hello, CodePlay!")\nprint("Let\'s go, " + name)\n';
const storageKey = 'codeplay-v1';
const emptyState = () => ({ code: defaultCode, completed: [], dates: [], language: 'en', theme: 'dark' });
let state = emptyState();
try {
  const stored = JSON.parse(localStorage.getItem(storageKey) || 'null');
  if (stored && typeof stored === 'object') {
    state.code = typeof stored.code === 'string' ? stored.code : defaultCode;
    state.completed = Array.isArray(stored.completed) && stored.completed.includes('print-spell') ? ['print-spell'] : [];
    state.dates = Array.isArray(stored.dates) ? [...new Set(stored.dates.filter(date => /^\d{4}-\d{2}-\d{2}$/.test(date)))].sort() : [];
    state.language = stored.language === 'fa' ? 'fa' : 'en';
    state.theme = stored.theme === 'light' ? 'light' : 'dark';
  }
} catch {}
let worker;
let runTimer;
let running = false;
let checks = [false, false, false];
let validatedCode = null;
let lastOutput = '';
let noticeTimer;
const main = document.querySelector('#main');
const modal = document.querySelector('#modal');
const t = key => translations[state.language][key] || translations.en[key] || key;
const escapeHtml = text => String(text).replace(/[&<>"']/g, character => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[character]);
const number = value => new Intl.NumberFormat(state.language === 'fa' ? 'fa-IR' : 'en-US').format(value);
const localDate = (date = new Date()) => `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}-${String(date.getDate()).padStart(2, '0')}`;
const xp = () => state.completed.length * 50;
function streak() {
  const date = new Date();
  if (!state.dates.includes(localDate(date))) date.setDate(date.getDate() - 1);
  let count = 0;
  while (state.dates.includes(localDate(date))) {
    count += 1;
    date.setDate(date.getDate() - 1);
  }
  return count;
}
function save() {
  try { localStorage.setItem(storageKey, JSON.stringify(state)); } catch { showNotice(state.language === 'fa' ? 'ذخیره محلی در این مرورگر در دسترس نیست.' : 'Local storage is unavailable in this browser.'); }
}
function showNotice(message) {
  const notice = document.querySelector('#notice');
  notice.textContent = message;
  notice.hidden = false;
  clearTimeout(noticeTimer);
  noticeTimer = setTimeout(() => { notice.hidden = true; }, 6000);
}
function sectionHead(eyebrow, title, text, centered = false) {
  return `<div class="section-heading ${centered ? 'center' : ''}"><div class="eyebrow">${t(eyebrow)}</div><h2>${t(title)}</h2><p>${t(text)}</p></div>`;
}
const primary = (route = 'dashboard') => `<a href="#${route}" class="button">${t('start')} <span aria-hidden="true">↗</span></a>`;
function worldCards() {
  return [
    ['forest', 'forestText', '01', '♧', 'beginner', 'print("Hello, world!")', 'available', '#quest', 'Python پایتون variables متغیر loops حلقه functions تابع'],
    ['caverns', 'cavernsText', '02', '◇', 'intermediate', 'if courage > 0: explore()', 'roadmap', '#', 'logic منطق lists لیست conditions شرط'],
    ['city', 'cityText', '03', '♜', 'advanced', 'path("", views.home)', 'proAccess', '#', 'Django جنگو routes مسیر models مدل web وب']
  ].map(([title, text, world, symbol, difficulty, code, availability, route, search]) => `<article class="card world" data-search="${escapeHtml(`${t(title)} ${t(text)} ${search}`.toLowerCase())}"><div class="world-symbol" aria-hidden="true">${symbol}</div><div class="eyebrow">WORLD ${world} · ${world === '01' ? t('free') : t('coming')}</div><h3>${t(title)}</h3><p>${t(text)}</p><code dir="ltr">${escapeHtml(code)}</code><div class="meta">${t(difficulty)} · ${t(availability)}</div>${route === '#' ? `<button class="button secondary" data-info="${world === '03' ? 'pro' : 'roadmap'}">${t('coming')}</button>` : `<a class="button secondary" href="${route}">${t('continue')} →</a>`}</article>`).join('');
}
function stats(full = true) {
  const items = full ? [[number(xp()) + ' XP', 'xp', 'xpText'], [number(state.completed.length), 'badges', 'badgeText'], [number(streak()), 'streak', 'streakText'], [t('rank'), 'leaderboard', 'rankText']] : [[number(xp()), 'xp', null], [number(state.completed.length), 'completeCount', null], [number(streak()), 'streak', null]];
  return `<div class="grid ${full ? 'four' : 'three'}">${items.map(([value, label, description], index) => `<article class="card stat"><span class="stat-icon" aria-hidden="true">${['⌘', '◇', 'ϟ', '↗'][index]}</span><div class="stat-number">${value}</div><h3 style="font-size:14px">${t(label)}</h3>${description ? `<p>${t(description)}</p>` : ''}</article>`).join('')}</div>`;
}
