function renderHome() {
  main.innerHTML = `<div class="container"><section class="hero" id="home"><div><div class="eyebrow">${t('tagline')}</div><h1>${t('hero')}</h1><p>${t('heroText')}</p><div class="actions">${primary()}<a class="button secondary" href="#quests">${t('explore')} →</a></div><div class="assurances"><span>${t('noExperience')}</span><span>${t('noInstall')}</span><span>${t('noCard')}</span></div></div><div class="hero-art"><span class="art-top">YOUR ADVENTURE STARTS HERE</span><img src="assets/hero.webp" alt="Pip exploring a magical coding island with a glowing portal" fetchpriority="high"><div class="art-caption"><strong>${t('firstLine')}</strong><small>${t('firstLevel')}</small></div></div></section><div class="proof"><strong>${t('honest')}</strong><span>${t('realCode')}</span><span>${t('playFirst')}</span><span>${t('minutes')}</span></div></div><section class="section" id="how"><div class="container">${sectionHead('different', 'less', 'journey')}<div class="grid three">${[['pick', 'pickText'], ['codeWay', 'codeText'], ['level', 'levelText']].map(([title, text], index) => `<article class="card"><span class="step-number">0${index + 1}</span><h3>${t(title)}</h3><p>${t(text)}</p></article>`).join('')}</div></div></section><section class="section" id="quests"><div class="container"><div class="search-row">${sectionHead('mapEyebrow', 'mapTitle', 'mapText')}<div><label class="sr-only" for="quest-search">${t('search')}</label><input id="quest-search" type="search" placeholder="${t('search')}"></div></div><div class="grid three" id="worlds">${worldCards()}</div><p id="no-results" class="empty" hidden>${t('noResults')}</p></div></section><section class="section"><div class="container">${sectionHead('progressEyebrow', 'progressTitle', 'progressText')}${stats()}</div></section><section class="section" id="demo"><div class="container">${sectionHead('playgroundEyebrow', 'playgroundTitle', 'playgroundText')}${editorMarkup()}</div></section><section class="section" id="community"><div class="container">${sectionHead('storiesEyebrow', 'storiesTitle', 'storiesText')}<div class="grid three">${['Sam Rivera', 'Maya Chen', 'Jordan Ellis'].map((name, index) => `<article class="card"><span class="quote-label">${t('sampleStory')}</span><div class="stars" aria-label="Illustrative five stars">★★★★★</div><p>${t('quote' + (index + 1))}</p><div class="person">${avatar(index)}<div><strong>${name}</strong><small>${t('role' + (index + 1))}</small></div></div></article>`).join('')}</div></div></section>${pricingMarkup()}<section class="section" id="faq"><div class="container faq-layout">${sectionHead('faqEyebrow', 'faqTitle', 'faqText')}<div>${[1, 2, 3, 4, 5].map(index => `<details><summary>${t('faq' + index)}</summary><p>${t('answer' + index)}</p></details>`).join('')}</div></div></section><section class="cta-band"><div class="container"><div class="cta-copy"><img src="assets/pip.webp" alt=""><div><h2>${t('ctaTitle')}</h2><p>${t('ctaText')}</p></div></div>${primary()}</div></section>`;
}
function sidebar() {
  return `<aside class="sidebar" aria-label="Learning navigation"><a class="active" href="#dashboard">◇ &nbsp; ${t('dashboard')}</a><a href="#practice">⌘ &nbsp; ${t('practice')}</a><a href="#badges">⬡ &nbsp; ${t('badges')}</a><a href="#" data-info="community">↗ &nbsp; ${t('leaderboard')}</a><a href="#" data-info="help">☷ &nbsp; ${t('resources')}</a></aside>`;
}
function habitMarkup() {
  const days = [];
  for (let offset = 6; offset >= 0; offset -= 1) {
    const date = new Date();
    date.setDate(date.getDate() - offset);
    days.push(`<span class="${state.dates.includes(localDate(date)) ? 'done' : ''}" title="${localDate(date)}">${new Intl.DateTimeFormat(state.language === 'fa' ? 'fa-IR' : 'en-US', { weekday: 'narrow' }).format(date)}</span>`);
  }
  return `<article class="card"><h3>${t('keepFire')}</h3><p>${t('keepText')}</p><div class="week">${days.join('')}</div><progress value="${state.dates.includes(localDate()) ? 50 : 0}" max="50" aria-label="${t('daily')}"></progress><div class="meta">${number(state.dates.includes(localDate()) ? 50 : 0)} / ${number(50)} XP · ${t('daily')}</div></article>`;
}
function renderDashboard(badgesOnly = false) {
  main.innerHTML = `<div class="container dashboard-shell">${sidebar()}<div class="dashboard-content"><div class="eyebrow">${t('localOnly')}</div><h1>${t(state.completed.length ? 'welcomeBack' : 'welcome')}</h1><p>${t('dashboardText')}</p>${stats(false)}${badgesOnly ? `<article class="card" style="margin-top:24px"><div class="badge-art" aria-hidden="true">⬡</div><h2 class="center">${state.completed.length ? t('spellCaster') : t('nextBadge')}</h2><p class="center">${t(state.completed.length ? 'congratsText' : 'noBadges')}</p><div class="center"><a class="button" href="#quest">${t(state.completed.length ? 'replay' : 'continue')}</a></div></article>` : `<div class="dashboard-columns"><article class="card map-card"><div class="map-title"><div class="eyebrow">PYTHON PATH</div><h3>${t('forest')}</h3><div class="meta">${number(state.completed.length)} ${t('forestProgress')}</div></div><div class="quest-map">${[['spell', false], ['goal1', true], ['caverns', true], ['city', true]].map(([label, locked], index) => `<div class="quest-node ${index === 0 && state.completed.length ? 'done' : ''}"><span class="node-icon" aria-hidden="true">${locked ? '⌑' : state.completed.length ? '✓' : '▶'}</span>${locked ? `<span class="meta">${t(label)}<br>${t('coming')}</span>` : `<a href="#quest"><strong>${t(label)}</strong><br><span class="meta">+50 XP · ${t('beginner')}</span></a>`}</div>`).join('')}<img src="assets/pip.webp" alt="Pip cheering you on" width="90"></div><div class="card" style="border:0;border-radius:0"><div class="eyebrow">${t('next')}</div><h3>${t('spell')}</h3><a class="button" href="#quest">${t(state.completed.length ? 'replay' : 'continue')} →</a></div></article><div class="stack">${habitMarkup()}<article class="card"><div class="eyebrow">${t(state.completed.length ? 'earned' : 'nextBadge')}</div><h3>${t('spellCaster')}</h3><p>${t('badgeDescription')}</p><progress value="${state.completed.length ? 3 : checks.filter(Boolean).length}" max="3" aria-label="${t('goals')}"></progress></article><article class="card" style="background:var(--glow)"><h3>${t('nextWorld')}</h3><p>${t('nextWorldText')}</p><button class="button small" data-info="pro" style="margin-top:15px">${t('proButton')}</button></article></div></div>`}</div></div>`;
}
function renderQuest(practice = false) {
  main.innerHTML = `<div class="container quest-layout"><aside class="quest-instructions"><a class="text-link meta" href="#dashboard">← ${t('dashboard')}</a><div class="eyebrow" style="margin-top:25px">PYTHON · ${t('beginner')} · +50 XP</div><h2>${t(practice ? 'practice' : 'spell')}</h2><p style="font-size:14px">${t('questDescription')}</p><div class="card"><h3>${t('goals')}</h3><ul class="goals">${goalMarkup()}</ul><button class="button secondary small" id="show-hint" aria-expanded="false">${t('hints')}</button><p class="hint" id="quest-hint" hidden>${t('hintText')}</p></div></aside><div>${editorMarkup(!practice)}<article class="card" style="margin-top:20px"><h3>${t('hintBot')}</h3><p>${t('hintSubtitle')}</p><form id="hint-form" style="display:flex;gap:10px;margin-top:15px"><label class="sr-only" for="hint-question">${t('ask')}</label><input id="hint-question" placeholder="${t('ask')}" maxlength="300" style="min-width:0;flex:1" required><button class="button small">${t('askButton')}</button></form><p id="hint-answer" class="hint" aria-live="polite">${t('tip')}</p><small class="meta">${t('hintDisclaimer')}</small></article></div></div>`;
}
function renderFooter() {
  document.querySelector('#footer').innerHTML = `<div class="container"><div class="footer-grid"><div><a class="brand" href="#home"><img src="assets/logo.svg" alt="" width="26" height="26"><span>Code<span>Play</span></span></a><p>${t('footerText')}</p></div><div><h3>${t('explore')}</h3><div class="footer-links"><a href="#quests">${t('quests')}</a><a href="#pricing">${t('pricing')}</a><a href="#" data-info="community">${t('leaderboard')}</a><a href="#community">${t('community')}</a></div></div><div><h3>${t('company')}</h3><div class="footer-links">${['about', 'help', 'privacy', 'terms', 'accessibility'].map(key => `<a href="#" data-info="${key}">${t(key)}</a>`).join('')}</div></div><form class="newsletter"><h3>${t('newsletterTitle')}</h3><p>${t('newsletterText')}</p><label for="email">${t('email')}</label><div class="newsletter-row"><input id="email" type="email" placeholder="you@example.com" disabled><button type="button" class="button small" disabled>${t('join')}</button></div><label class="consent"><input type="checkbox" disabled><span>${t('consent')} <a class="text-link" href="#" data-info="privacy">${t('privacy')}</a></span></label></form></div><div class="copyright"><span>© ${new Date().getFullYear()} CodePlay. ${t('rights')}</span><span>${t('made')}</span></div></div>`;
}
function render(scroll = true) {
  stopRun();
  document.documentElement.lang = state.language;
  document.documentElement.dir = state.language === 'fa' ? 'rtl' : 'ltr';
  document.documentElement.dataset.theme = state.theme;
  document.querySelector('#language').value = state.language;
  document.querySelector('#theme').textContent = state.theme === 'dark' ? '☼' : '☾';
  document.querySelector('#theme').setAttribute('aria-label', t('themeLabel'));
  document.querySelector('#back-top').setAttribute('aria-label', state.language === 'fa' ? 'بازگشت به بالا' : 'Back to top');
  document.querySelector('#menu').setAttribute('aria-label', state.language === 'fa' ? 'باز و بسته کردن منو' : 'Toggle menu');
  document.querySelector('#modal .close').setAttribute('aria-label', state.language === 'fa' ? 'بستن پنجره' : 'Close dialog');
  document.querySelector('.skip').textContent = state.language === 'fa' ? 'پرش به محتوا' : 'Skip to content';
  document.querySelector('[for="language"]').textContent = t('langLabel');
  document.querySelectorAll('[data-i18n]').forEach(element => { element.textContent = t(element.dataset.i18n); });
  const route = location.hash.slice(1) || 'home';
  document.title = `CodePlay — ${t(route === 'quest' ? 'spell' : route === 'dashboard' ? 'dashboard' : route === 'practice' ? 'practice' : route === 'badges' ? 'badges' : 'tagline')}`;
  document.querySelector('#navigation').innerHTML = ['how', 'quests', 'community', 'pricing'].map(key => `<a href="#${key}" class="${route === key ? 'active' : ''}">${t(key)}</a>`).join('');
  document.querySelector('#navigation').classList.remove('open');
  document.querySelector('#menu').setAttribute('aria-expanded', 'false');
  if (route === 'dashboard' || route === 'badges') renderDashboard(route === 'badges');
  else if (route === 'quest' || route === 'practice') renderQuest(route === 'practice');
  else renderHome();
  renderFooter();
  bindPage();
  if (scroll) requestAnimationFrame(() => {
    const target = document.getElementById(route);
    if (target && route !== 'home') target.scrollIntoView();
    else window.scrollTo({ top: 0 });
  });
}
function highlightCode(code) {
  return code.split('\n').map(line => {
    const pattern = /("(?:[^"\\]|\\.)*"|'(?:[^'\\]|\\.)*'|#.*$|\b(?:print|if|else|for|in|def|return|import|from|while|True|False|None)\b|\b\d+\b)/g;
    let html = '';
    let cursor = 0;
    for (const match of line.matchAll(pattern)) {
      html += escapeHtml(line.slice(cursor, match.index));
      const token = match[0];
      const kind = token.startsWith('#') ? 'comment' : /^["']/.test(token) ? 'string' : /^\d/.test(token) ? 'number' : 'keyword';
      html += `<span class="syntax-${kind}">${escapeHtml(token)}</span>`;
      cursor = match.index + token.length;
    }
    return html + escapeHtml(line.slice(cursor));
  }).join('\n') + '\n';
}
function updateHighlight() {
  const highlight = document.querySelector('.code-highlight');
  if (highlight) highlight.innerHTML = highlightCode(state.code);
}
function invalidateChecks() {
  checks = [false, false, false];
  validatedCode = null;
  updateChecks();
}
function updateChecks() {
  const list = document.querySelector('#quest-checks');
  if (list) list.innerHTML = goalMarkup();
  const instructionGoals = document.querySelector('.quest-instructions .goals');
  if (instructionGoals) instructionGoals.innerHTML = goalMarkup();
  const count = document.querySelector('#check-count');
  if (count) count.textContent = `${number(checks.filter(Boolean).length)} / ${number(3)} ${t('passed')}`;
  const button = document.querySelector('#complete-quest');
  if (button) button.disabled = !checks.every(Boolean) || validatedCode !== state.code || state.completed.length > 0;
}
function stopRun() {
  clearTimeout(runTimer);
  if (running && worker) { worker.terminate(); worker = null; }
  if (running) { checks = [false, false, false]; validatedCode = null; }
  running = false;
}
function finishRun() {
  clearTimeout(runTimer);
  running = false;
  const button = document.querySelector('#run-code');
  if (button) { button.disabled = false; button.textContent = t('run') + ' ▶'; }
}
function runCode() {
  if (running) return;
  invalidateChecks();
  lastOutput = '';
  running = true;
  const code = state.code;
  const button = document.querySelector('#run-code');
  button.disabled = true;
  button.textContent = t('running');
  document.querySelector('#execution-status').textContent = t('running');
  document.querySelector('#console').classList.remove('error');
  if (!worker) worker = new Worker(new URL('./python-worker.js', import.meta.url));
  const failed = message => {
    document.querySelector('#output').textContent = message;
    document.querySelector('#console').classList.add('error');
    document.querySelector('#execution-status').textContent = t('ready');
    document.querySelector('#preview-message').textContent = t('previewReady');
    invalidateChecks();
    finishRun();
  };
  worker.onmessage = ({ data }) => {
    if (data.error) { failed(data.error); return; }
    lastOutput = data.output;
    checks = code === state.code ? data.checks : [false, false, false];
    validatedCode = code === state.code ? code : null;
    document.querySelector('#output').textContent = data.output || t('emptyOutput');
    document.querySelector('#execution-status').textContent = t('successful');
    document.querySelector('#preview-message').textContent = data.output ? t('previewSuccess') : t('previewReady');
    updateChecks();
    finishRun();
  };
  worker.onerror = () => { worker.terminate(); worker = null; failed(t('loadError')); };
  runTimer = setTimeout(() => { worker.terminate(); worker = null; failed(t('timeout')); }, 60000);
  worker.postMessage({ code });
}
function completeQuest() {
  if (!checks.every(Boolean) || validatedCode !== state.code || state.completed.includes('print-spell')) return;
  state.completed.push('print-spell');
  if (!state.dates.includes(localDate())) state.dates.push(localDate());
  state.dates.sort();
  save();
  updateChecks();
  const button = document.querySelector('#complete-quest');
  button.textContent = t('completed');
  document.querySelector('#modal-content').innerHTML = `<div class="success"><div class="eyebrow">${t('earned')}</div><div class="badge-art" aria-hidden="true">⬡</div><div class="eyebrow">${t('spellCaster')}</div><h2>${t('congrats')}</h2><p>${t('congratsText')}</p><span class="pill">+50 XP</span><span class="pill">${number(xp())} XP</span><div class="actions" style="justify-content:center"><a class="button" href="#dashboard" id="continue-adventure">${t('adventure')}</a><a class="button secondary" href="#badges" id="view-badges">${t('badges')}</a></div></div>`;
  modal.showModal();
  modal.querySelectorAll('a').forEach(link => link.addEventListener('click', () => modal.close()));
}
function openInfo(kind) {
  const info = { pro: ['pro', 'proInfo'], community: ['community', 'communityInfo'], about: ['about', 'aboutText'], help: ['help', 'helpText'], privacy: ['privacy', 'privacyText'], terms: ['terms', 'termsText'], accessibility: ['accessibility', 'accessibilityText'], roadmap: ['coming', 'unavailable'] }[kind] || ['help', 'helpText'];
  document.querySelector('#modal-content').innerHTML = `<h2>${t(info[0])}</h2><p>${t(info[1])}</p>${kind === 'privacy' ? `<button class="button secondary" id="clear-progress">${t('resetProgress')}</button>` : kind === 'pro' || kind === 'roadmap' ? primary('quest') : ''}`;
  modal.showModal();
  modal.querySelectorAll('a').forEach(link => link.addEventListener('click', () => modal.close()));
  document.querySelector('#clear-progress')?.addEventListener('click', () => {
    document.querySelector('#modal-content').innerHTML = `<h2>${t('resetProgress')}</h2><p>${t('resetConfirm')}</p><button class="button" id="confirm-clear">${t('resetProgress')}</button>`;
    document.querySelector('#confirm-clear').addEventListener('click', () => {
      state = { ...emptyState(), language: state.language, theme: state.theme };
      checks = [false, false, false];
      lastOutput = '';
      validatedCode = null;
      save();
      modal.close();
      render(false);
      showNotice(t('resetDone'));
    });
  });
}
function bindPage() {
  document.querySelectorAll('[data-info]').forEach(element => element.addEventListener('click', event => { event.preventDefault(); openInfo(element.dataset.info); }));
  document.querySelector('#quest-search')?.addEventListener('input', event => {
    const query = event.target.value.trim().toLowerCase();
    let found = 0;
    document.querySelectorAll('[data-search]').forEach(card => { card.hidden = !card.dataset.search.includes(query); if (!card.hidden) found += 1; });
    document.querySelector('#no-results').hidden = found > 0;
  });
  const input = document.querySelector('#code-input');
  if (input) {
    updateHighlight();
    input.addEventListener('input', () => { state.code = input.value; invalidateChecks(); updateHighlight(); save(); });
    input.addEventListener('scroll', () => { const highlight = document.querySelector('.code-highlight'); highlight.scrollTop = input.scrollTop; highlight.scrollLeft = input.scrollLeft; });
    input.addEventListener('keydown', event => {
      if ((event.ctrlKey || event.metaKey) && event.key === 'Enter') { event.preventDefault(); runCode(); }
      if (event.key === 'Tab') {
        event.preventDefault();
        input.setRangeText('    ', input.selectionStart, input.selectionEnd, 'end');
        input.dispatchEvent(new Event('input'));
      }
    });
    document.querySelector('#run-code').addEventListener('click', runCode);
    document.querySelector('#reset-code').addEventListener('click', () => {
      if (running) { stopRun(); finishRun(); }
      state.code = defaultCode;
      input.value = defaultCode;
      lastOutput = '';
      document.querySelector('#output').textContent = '>>>';
      document.querySelector('#preview-message').textContent = t('previewReady');
      document.querySelector('#execution-status').textContent = t('ready');
      document.querySelector('#console').classList.remove('error');
      invalidateChecks(); updateHighlight(); save();
    });
  }
  document.querySelector('#complete-quest')?.addEventListener('click', completeQuest);
  document.querySelector('#show-hint')?.addEventListener('click', event => {
    const hint = document.querySelector('#quest-hint');
    hint.hidden = !hint.hidden;
    event.currentTarget.setAttribute('aria-expanded', String(!hint.hidden));
  });
  document.querySelector('#hint-form')?.addEventListener('submit', event => {
    event.preventDefault();
    const query = document.querySelector('#hint-question').value.toLowerCase();
    const key = /print|چاپ/.test(query) ? 'hintPrint' : /variable|name|متغیر/.test(query) ? 'hintVariable' : /error|خطا|quote|کوتیشن/.test(query) ? 'hintError' : 'hintDefault';
    document.querySelector('#hint-answer').textContent = t(key);
  });
}
document.querySelector('#language').addEventListener('change', event => { state.language = event.target.value; save(); render(false); });
document.querySelector('#theme').addEventListener('click', () => {
  state.theme = state.theme === 'dark' ? 'light' : 'dark';
  document.documentElement.dataset.theme = state.theme;
  document.querySelector('#theme').textContent = state.theme === 'dark' ? '☼' : '☾';
  save();
});
document.querySelector('#menu').addEventListener('click', event => {
  const open = document.querySelector('#navigation').classList.toggle('open');
  event.currentTarget.setAttribute('aria-expanded', String(open));
});
document.querySelector('#back-top').addEventListener('click', () => window.scrollTo({ top: 0, behavior: matchMedia('(prefers-reduced-motion: reduce)').matches ? 'instant' : 'smooth' }));
window.addEventListener('scroll', () => { document.querySelector('#back-top').hidden = window.scrollY < 450; }, { passive: true });
document.querySelector('#modal .close').addEventListener('click', () => modal.close());
modal.addEventListener('click', event => { if (event.target === modal) { const rect = modal.getBoundingClientRect(); if (event.clientX < rect.left || event.clientX > rect.right || event.clientY < rect.top || event.clientY > rect.bottom) modal.close(); } });
window.addEventListener('hashchange', () => { if (modal.open) modal.close(); render(); });
render();
